mapper.select:
SELECT id, SHA2(CAST(JSON_ARRAY(id, enterprise_id, warehouse_id, operation_id, entry_no, balance_id, on_hand_delta, reserved_delta, free_execution_claim_delta, on_hand_after, reserved_after, free_execution_claim_after, balance_version, reason_code, document_id, actor_id, occurred_at, created_at) AS CHAR),256) AS payload_hash
FROM stock_ledger WHERE enterprise_id=#{enterprise} AND warehouse_id=#{warehouse}
    AND occurred_at < #{cutoff} AND created_at < #{cutoff}
AND id > #{cursor}
ORDER BY id LIMIT 201
